<?php $old=$_SESSION['homeData']??[];unset($_SESSION['homeData']);$value=fn($k,$d='')=>$old[$k]??$home[$k]??$d;$class='mt-1 block w-full rounded-lg border border-slate-300 px-3 py-2.5 text-sm'; ?><form method="post" action="<?= e(APP_URL.'/families/'.(int)$home['family_id'].'/home/update') ?>" class="space-y-6"><section class="rounded-xl border border-slate-200 bg-white p-6 shadow-sm"><div class="grid gap-5 md:grid-cols-2"><label class="text-sm font-medium text-slate-700 md:col-span-2">Address<textarea required name="address" rows="3" class="<?= $class ?>"><?= e($value('address')) ?></textarea></label><label class="text-sm font-medium text-slate-700">Status<select name="status" class="<?= $class ?>"><?php foreach(['Active','Inactive','Transferred'] as $s): ?><option <?= $value('status')===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach; ?></select></label><label class="text-sm font-medium text-slate-700 md:col-span-2">Remarks<textarea name="remarks" rows="4" class="<?= $class ?>"><?= e($value('remarks')) ?></textarea></label></div></section><div class="flex justify-end gap-3"><a href="<?= e(APP_URL.'/families/'.(int)$home['family_id'].'/home') ?>" class="rounded-lg border border-slate-300 px-4 py-2.5 text-sm font-semibold">Cancel</a><button class="rounded-lg bg-blue-600 px-5 py-2.5 text-sm font-semibold text-white">Save Household</button></div></form>
